class Solution:
    def judgeCircle(self, moves: str) -> bool:
        return moves.count('U') == moves.count('D') and moves.count('L') == moves.count('R')

class Solution {
public:
    bool judgeCircle(string moves) {
        int x = 0, y = 0;
        for (char c : moves) {
            if (c == 'U') y++;
            else if (c == 'D') y--;
            else if (c == 'R') x++;
            else if (c == 'L') x--;
        }
        return x == 0 && y == 0;
    }
};

class Solution {
    public boolean judgeCircle(String moves) {
        int x = 0, y = 0;
        for (char c : moves.toCharArray()) {
            if (c == 'U') y++;
            else if (c == 'D') y--;
            else if (c == 'R') x++;
            else if (c == 'L') x--;
        }
        return x == 0 && y == 0;
    }
}

var judgeCircle = function(moves) {
    let x = 0, y = 0;
    for (let i = 0; i < moves.length; i++) {
        const c = moves[i];
        if (c === 'U') y++;
        else if (c === 'D') y--;
        else if (c === 'R') x++;
        else if (c === 'L') x--;
    }
    return x === 0 && y === 0;
};
